'use client';

import { FormEvent, ReactNode, useEffect, useMemo, useRef, useState } from 'react';
import {
  Activity, Bell, BookOpen, Bot, Camera, Check, ChevronRight, CircleUserRound,
  ClipboardCheck, FileText, FolderOpen, Globe2, Home, Loader2, Menu as MenuIcon,
  MoreHorizontal, Plus, RefreshCw, Search, Settings, Sparkles, Upload, Users,
  WifiOff, X, LogOut, ShieldCheck, History, CheckCircle2, Circle, Mic, Trash2,
  Download, UserPlus, KeyRound
} from 'lucide-react';
import { supabase } from '@/lib/supabase';
import { safeStorageSegment,strongEnoughPassword,validFileName } from '@/lib/app-hardening';
import { safeInternalHref } from '@/lib/round3-hardening';
import { LanguageToggle, useI18n } from '@/lib/i18n';

type Tab = 'home' | 'operations' | 'team' | 'ai' | 'more';
type MoreSection = 'root' | 'knowledge' | 'files' | 'activity' | 'settings' | 'admin';
type AIMode = 'auto' | 'internal' | 'web';
type Profile = { full_name: string | null; app_role: 'admin'|'manager'|'employee'; location_id: string | null };
type Area = { id:string; name:string };
type Station = { id:string; name:string; description:string|null; area_id:string };
type KnowledgeItem = { id:string; title:string; content:string; status:string; station_id:string|null; category:string|null; created_at?:string };
type Procedure = { id:string; title:string; description:string|null; status:string; station_id:string|null; created_at?:string };
type Role = { id:string; name:string };
type Employee = { id:string; full_name:string; phone:string|null; active:boolean; start_date?:string|null };
type Task = { id:string; title:string; description:string|null; status:string; priority:string; due_at:string|null; assigned_employee_id:string|null; created_at:string };
type Notice = { id:string; title:string; body:string|null; href:string|null; read_at:string|null; created_at:string; type:string };
type ActivityRow = { id:string; action:string; summary:string|null; entity_type:string|null; created_at:string };
type FileRow = { id:string; file_name:string; kind:string; title:string|null; mime_type:string|null; size_bytes:number|null; storage_path:string; created_at:string };
type Prefs = { remember_email:boolean; email_notifications:boolean; push_notifications:boolean; in_app_notifications:boolean; reduced_motion:boolean; compact_mode:boolean; theme:'system'|'light'|'dark'; locale:string };
type SearchResult = { entity_type:string; entity_id:string; title:string; subtitle:string; href:string; rank:number };
type AIConversation = { id:string; title:string; source_mode:AIMode; updated_at:string };
type AIMessage = { id:string; role:'user'|'assistant'; content:string; source_label:string|null; feedback:number|null; created_at:string };

const defaultPrefs: Prefs = { remember_email:true, email_notifications:true, push_notifications:true, in_app_notifications:true, reduced_motion:false, compact_mode:false, theme:'system', locale:'en-US' };
const MAX_ROOT_UPLOAD_BYTES=50*1024*1024;

function useRootT(){
  const {locale}=useI18n();
  return {locale,t:(en:string,es:string)=>locale==='es'?es:en};
}

export default function AppPage() {
  const {locale,t}=useRootT();
  const [ready,setReady]=useState(false);
  const [signedIn,setSignedIn]=useState(false);
  const [loading,setLoading]=useState(false);
  const [profile,setProfile]=useState<Profile|null>(null);
  const [userEmail,setUserEmail]=useState('');
  const [tab,setTab]=useState<Tab>('home');
  const [moreSection,setMoreSection]=useState<MoreSection>('root');
  const [message,setMessage]=useState('');
  const [online,setOnline]=useState(true);
  const [showOnboarding,setShowOnboarding]=useState(false);
  const [showAccount,setShowAccount]=useState(false);
  const [showSearch,setShowSearch]=useState(false);
  const [showNotices,setShowNotices]=useState(false);

  const [email,setEmail]=useState('');
  const [password,setPassword]=useState('');
  const [fullName,setFullName]=useState('');
  const [authMode,setAuthMode]=useState<'signin'|'signup'>('signin');
  const [authBusy,setAuthBusy]=useState(false);
  const [taskBusy,setTaskBusy]=useState(false);
  const [writeBusy,setWriteBusy]=useState(false);
  const [uploadBusy,setUploadBusy]=useState(false);
  const [unreadTotal,setUnreadTotal]=useState(0);

  const [areas,setAreas]=useState<Area[]>([]);
  const [stations,setStations]=useState<Station[]>([]);
  const [knowledge,setKnowledge]=useState<KnowledgeItem[]>([]);
  const [procedures,setProcedures]=useState<Procedure[]>([]);
  const [roles,setRoles]=useState<Role[]>([]);
  const [employees,setEmployees]=useState<Employee[]>([]);
  const [tasks,setTasks]=useState<Task[]>([]);
  const [notices,setNotices]=useState<Notice[]>([]);
  const [activity,setActivity]=useState<ActivityRow[]>([]);
  const [files,setFiles]=useState<FileRow[]>([]);
  const [prefs,setPrefs]=useState<Prefs>(defaultPrefs);

  const [stationName,setStationName]=useState('');
  const [stationDescription,setStationDescription]=useState('');
  const [selectedStation,setSelectedStation]=useState('');
  const [knowledgeTitle,setKnowledgeTitle]=useState('');
  const [knowledgeContent,setKnowledgeContent]=useState('');
  const [procedureTitle,setProcedureTitle]=useState('');
  const [procedureDescription,setProcedureDescription]=useState('');
  const [employeeName,setEmployeeName]=useState('');
  const [employeePhone,setEmployeePhone]=useState('');
  const [taskTitle,setTaskTitle]=useState('');
  const [taskDue,setTaskDue]=useState('');

  const canManage=profile?.app_role==='admin'||profile?.app_role==='manager';
  const kitchenArea=useMemo(()=>areas.find(a=>a.name==='Kitchen'),[areas]);
  const unreadCount=unreadTotal;
  const openTasks=tasks.filter(t=>!['done','cancelled'].includes(t.status));

  useEffect(()=>{
    const remembered=localStorage.getItem('elmolino_email');
    if(remembered)setEmail(remembered);
    setShowOnboarding(localStorage.getItem('elmolino_onboarded')!=='1');
    const qs=new URLSearchParams(window.location.search); const requested=qs.get('tab') as Tab|null;
    if(requested&&['home','operations','team','ai','more'].includes(requested))setTab(requested);
    const sync=()=>setOnline(navigator.onLine); sync();
    window.addEventListener('online',sync);window.addEventListener('offline',sync);
    supabase.auth.getSession().then(({data})=>{setSignedIn(Boolean(data.session));setReady(true);if(data.session)void loadAll();});
    const {data:l}=supabase.auth.onAuthStateChange((_e,s)=>{setSignedIn(Boolean(s));if(s)void loadAll();else{setProfile(null);setUserEmail('');setUnreadTotal(0);}});
    return()=>{l.subscription.unsubscribe();window.removeEventListener('online',sync);window.removeEventListener('offline',sync);};
  },[]);

  useEffect(()=>{
    if(!ready)return;
    const draft=localStorage.getItem('elmolino_knowledge_draft');
    if(draft&&!knowledgeContent){try{const d=JSON.parse(draft);setKnowledgeTitle(d.title||'');setKnowledgeContent(d.content||'');}catch{}}
  },[ready]);
  useEffect(()=>{if(knowledgeTitle||knowledgeContent)localStorage.setItem('elmolino_knowledge_draft',JSON.stringify({title:knowledgeTitle,content:knowledgeContent}));},[knowledgeTitle,knowledgeContent]);
  useEffect(()=>{document.documentElement.dataset.theme=prefs.theme;document.documentElement.dataset.compact=String(prefs.compact_mode);document.documentElement.dataset.motion=prefs.reduced_motion?'reduced':'normal';},[prefs]);

  async function loadAll(){
    setLoading(true);setMessage('');
    const {data:a}=await supabase.auth.getUser();if(!a.user){setLoading(false);return;}
    setUserEmail(a.user.email||'');
    const [p,ar,st,k,pr,r,e,taskRows,n,nc,ac,f,pref]=await Promise.all([
      supabase.from('profiles').select('full_name,app_role,location_id').eq('id',a.user.id).single(),
      supabase.from('areas').select('id,name').order('name'),
      supabase.from('stations').select('id,name,description,area_id').order('created_at',{ascending:false}),
      supabase.from('knowledge_items').select('id,title,content,status,station_id,category,created_at').is('deleted_at',null).order('created_at',{ascending:false}).limit(200),
      supabase.from('procedures').select('id,title,description,status,station_id,created_at').is('deleted_at',null).order('created_at',{ascending:false}).limit(100),
      supabase.from('employee_roles').select('id,name').order('name'),
      supabase.from('employees').select('id,full_name,phone,active,start_date').is('deleted_at',null).order('full_name'),
      supabase.from('tasks').select('id,title,description,status,priority,due_at,assigned_employee_id,created_at').is('deleted_at',null).order('created_at',{ascending:false}).limit(100),
      supabase.from('notifications').select('id,title,body,href,read_at,created_at,type').order('created_at',{ascending:false}).limit(50),
      supabase.from('notifications').select('id',{count:'exact',head:true}).is('read_at',null),
      supabase.from('activity_log').select('id,action,summary,entity_type,created_at').order('created_at',{ascending:false}).limit(80),
      supabase.from('files').select('id,file_name,kind,title,mime_type,size_bytes,storage_path,created_at').is('deleted_at',null).order('created_at',{ascending:false}).limit(100),
      supabase.from('user_preferences').select('remember_email,email_notifications,push_notifications,in_app_notifications,reduced_motion,compact_mode,theme,locale').eq('user_id',a.user.id).maybeSingle()
    ]);
    const anyError=[p,ar,st,k,pr,r,e,taskRows,n,nc,ac,f,pref].some(x=>Boolean(x.error));
    if(p.error)setMessage(t('Your restaurant access profile could not be loaded.','No se pudo cargar tu perfil de acceso al restaurante.'));else if(anyError)setMessage(t('Some app data could not be loaded.','No se pudieron cargar algunos datos de la aplicación.'));
    if(p.data)setProfile(p.data as Profile);else setProfile(null);
    setAreas((ar.data??[]) as Area[]);setStations((st.data??[]) as Station[]);setKnowledge((k.data??[]) as KnowledgeItem[]);setProcedures((pr.data??[]) as Procedure[]);setRoles((r.data??[]) as Role[]);setEmployees((e.data??[]) as Employee[]);setTasks((taskRows.data??[]) as Task[]);setNotices((n.data??[]) as Notice[]);setUnreadTotal(nc.count??((n.data??[]) as Notice[]).filter(x=>!x.read_at).length);setActivity((ac.data??[]) as ActivityRow[]);setFiles((f.data??[]) as FileRow[]);if(pref.data)setPrefs(pref.data as Prefs);
    setLoading(false);
  }

  async function logActivity(action:string,entityType:string,entityId:string|null,summary:string){
    const {data:u}=await supabase.auth.getUser();if(!u.user||!profile?.location_id)return;
    await supabase.from('activity_log').insert({location_id:profile.location_id,actor_user_id:u.user.id,action,entity_type:entityType,entity_id:entityId,summary});
  }
  function flash(text:string){setMessage(text);window.setTimeout(()=>setMessage(''),3500);}
  async function auth(e:FormEvent){
    e.preventDefault();if(authBusy)return;setAuthBusy(true);setMessage('');
    try{
      if(authMode==='signup'){
        if(!strongEnoughPassword(password))throw new Error(t('Use at least 10 characters with letters and a number.','Usa al menos 10 caracteres con letras y un número.'));
        const {error}=await supabase.auth.signUp({email:email.trim().toLowerCase(),password,options:{data:{full_name:fullName.trim().slice(0,120)}}});if(error)throw error;
        flash(t('Invited account created. Confirm your email if prompted, then sign in.','Cuenta invitada creada. Confirma tu correo si se solicita y luego inicia sesión.'));
      }else{
        const {error}=await supabase.auth.signInWithPassword({email:email.trim().toLowerCase(),password});if(error)throw error;
        if(prefs.remember_email!==false)localStorage.setItem('elmolino_email',email.trim().toLowerCase());
      }
    }catch(err){setMessage(err instanceof Error?err.message:t('Could not sign in.','No se pudo iniciar sesión.'));}finally{setAuthBusy(false);}
  }
  async function forgotPassword(){if(!email.trim())return flash(t('Enter your email first.','Ingresa primero tu correo electrónico.'));const {error}=await supabase.auth.resetPasswordForEmail(email.trim().toLowerCase(),{redirectTo:`${window.location.origin}/`});flash(error?t('Could not send a password reset right now.','No se pudo enviar el restablecimiento de contraseña en este momento.'):t('Password reset email sent.','Correo de restablecimiento enviado.'));}
  async function updateName(){if(!profile)return;const name=prompt(t('Your name','Tu nombre'),profile.full_name||'');if(!name?.trim())return;const {data:u}=await supabase.auth.getUser();if(!u.user)return;const {error}=await supabase.from('profiles').update({full_name:name.trim().slice(0,120)}).eq('id',u.user.id);if(error)return flash(t('Could not update your profile.','No se pudo actualizar tu perfil.'));await loadAll();flash(t('Profile updated.','Perfil actualizado.'));}
  async function updatePrefs(patch:Partial<Prefs>){const {data:u}=await supabase.auth.getUser();if(!u.user)return;const previous=prefs,next={...prefs,...patch};setPrefs(next);const {error}=await supabase.from('user_preferences').upsert({user_id:u.user.id,...next,updated_at:new Date().toISOString()});if(error){setPrefs(previous);return flash(t('Could not save that preference.','No se pudo guardar esa preferencia.'))}if(!next.remember_email)localStorage.removeItem('elmolino_email');else if(userEmail)localStorage.setItem('elmolino_email',userEmail);}

  async function createStation(e:FormEvent){e.preventDefault();if(writeBusy||!kitchenArea||!stationName.trim())return;setWriteBusy(true);try{const {data,error}=await supabase.from('stations').insert({area_id:kitchenArea.id,name:stationName.trim().slice(0,200),description:stationDescription.trim().slice(0,2000)||null}).select('id').single();if(error)return flash(t('Could not add that station.','No se pudo agregar esa estación.'));const oldName=stationName;setStationName('');setStationDescription('');await logActivity('created','station',data.id,`Created station ${oldName.trim().slice(0,200)}`);await loadAll();flash(t('Station added.','Estación agregada.'))}finally{setWriteBusy(false)}}
  async function createKnowledge(e:FormEvent){e.preventDefault();if(writeBusy||!profile?.location_id||!knowledgeTitle.trim()||!knowledgeContent.trim())return;setWriteBusy(true);try{const st=stations.find(s=>s.id===selectedStation);const title=knowledgeTitle.trim().slice(0,200);const {data,error}=await supabase.from('knowledge_items').insert({location_id:profile.location_id,area_id:st?.area_id??kitchenArea?.id??null,station_id:selectedStation||null,title,content:knowledgeContent.trim().slice(0,20000),category:'operational_knowledge',status:'draft'}).select('id').single();if(error)return flash(t('Could not save that knowledge draft.','No se pudo guardar ese borrador de conocimiento.'));await logActivity('created','knowledge',data.id,`Added knowledge: ${title}`);setKnowledgeTitle('');setKnowledgeContent('');localStorage.removeItem('elmolino_knowledge_draft');await loadAll();flash(t('Knowledge draft saved.','Borrador de conocimiento guardado.'))}finally{setWriteBusy(false)}}
  async function approveKnowledge(id:string){if(writeBusy)return;setWriteBusy(true);try{const {data:a}=await supabase.auth.getUser();if(!a.user)return;const item=knowledge.find(k=>k.id===id);const {error}=await supabase.from('knowledge_items').update({status:'approved',approved_by:a.user.id,approved_at:new Date().toISOString()}).eq('id',id);if(error)return flash(t('Could not approve that knowledge record.','No se pudo aprobar ese registro de conocimiento.'));await logActivity('approved','knowledge',id,`Approved knowledge: ${item?.title||id}`);await loadAll();flash(t('Knowledge approved.','Conocimiento aprobado.'))}finally{setWriteBusy(false)}}
  async function softDeleteKnowledge(id:string){if(writeBusy||!confirm(t('Move this knowledge record to trash?','¿Mover este registro de conocimiento a la papelera?')))return;setWriteBusy(true);try{const item=knowledge.find(k=>k.id===id);const {error}=await supabase.from('knowledge_items').update({deleted_at:new Date().toISOString()}).eq('id',id).is('deleted_at',null);if(error)return flash(t('Could not move that knowledge record to trash.','No se pudo mover ese registro a la papelera.'));await logActivity('deleted','knowledge',id,`Moved ${item?.title||'knowledge'} to trash`);await loadAll();flash(t('Moved to trash.','Movido a la papelera.'))}finally{setWriteBusy(false)}}
  async function createProcedure(e:FormEvent){e.preventDefault();if(writeBusy||!profile?.location_id||!procedureTitle.trim())return;setWriteBusy(true);try{const st=stations.find(s=>s.id===selectedStation),title=procedureTitle.trim().slice(0,200);const {data,error}=await supabase.from('procedures').insert({location_id:profile.location_id,area_id:st?.area_id??kitchenArea?.id??null,station_id:selectedStation||null,title,description:procedureDescription.trim().slice(0,8000)||null,status:'draft'}).select('id').single();if(error)return flash(t('Could not create that procedure.','No se pudo crear ese procedimiento.'));await logActivity('created','procedure',data.id,`Created procedure ${title}`);setProcedureTitle('');setProcedureDescription('');await loadAll();flash(t('Procedure draft created.','Borrador de procedimiento creado.'))}finally{setWriteBusy(false)}}
  async function createEmployee(e:FormEvent){e.preventDefault();if(writeBusy||!profile?.location_id||!employeeName.trim())return;setWriteBusy(true);try{const name=employeeName.trim().slice(0,200);const {data,error}=await supabase.from('employees').insert({location_id:profile.location_id,full_name:name,phone:employeePhone.trim().slice(0,80)||null}).select('id').single();if(error)return flash(t('Could not add that team member.','No se pudo agregar a ese integrante del equipo.'));await logActivity('created','employee',data.id,`Added ${name}`);setEmployeeName('');setEmployeePhone('');await loadAll();flash(t('Team member added.','Integrante del equipo agregado.'))}finally{setWriteBusy(false)}}
  async function createTask(e:FormEvent){e.preventDefault();if(taskBusy||!profile?.location_id||!taskTitle.trim())return;setTaskBusy(true);try{const {data:u}=await supabase.auth.getUser();if(!u.user)return;const title=taskTitle.trim().slice(0,200),due=taskDue?new Date(taskDue):null;if(due&&!Number.isFinite(due.getTime()))return flash(t('Choose a valid due date and time.','Elige una fecha y hora de vencimiento válidas.'));const {data,error}=await supabase.from('tasks').insert({location_id:profile.location_id,title,due_at:due?due.toISOString():null,created_by:u.user.id}).select('id').single();if(error)return flash(t('Could not create that task.','No se pudo crear esa tarea.'));await logActivity('created','task',data.id,`Created task ${title}`);setTaskTitle('');setTaskDue('');await loadAll();flash(t('Task created.','Tarea creada.'))}finally{setTaskBusy(false)}}
  async function toggleTask(task:Task){if(taskBusy)return;setTaskBusy(true);try{const done=task.status!=='done';const {data,error}=await supabase.from('tasks').update({status:done?'done':'open',completed_at:done?new Date().toISOString():null,updated_at:new Date().toISOString()}).eq('id',task.id).eq('status',task.status).select('id').maybeSingle();if(error)return flash(t('Could not update that task.','No se pudo actualizar esa tarea.'));if(!data){await loadAll();return flash(t('That task changed on another device. The latest version has been loaded.','Esa tarea cambió en otro dispositivo. Se cargó la versión más reciente.'))}await logActivity(done?'completed':'reopened','task',task.id,`${done?'Completed':'Reopened'} task ${task.title}`);await loadAll();}finally{setTaskBusy(false)}}
  async function uploadFile(file:File){if(uploadBusy||!profile?.location_id)return;if(!validFileName(file.name))return flash(t('That file name is not valid.','Ese nombre de archivo no es válido.'));if(file.size<=0)return flash(t('That file is empty.','Ese archivo está vacío.'));if(file.size>MAX_ROOT_UPLOAD_BYTES)return flash(t('Files are limited to 50 MB.','Los archivos están limitados a 50 MB.'));setUploadBusy(true);try{const {data:u}=await supabase.auth.getUser();if(!u.user)return;const safe=safeStorageSegment(file.name),path=`${profile.location_id}/${u.user.id}/${Date.now()}-${crypto.randomUUID()}-${safe}`,mime=file.type||'application/octet-stream';flash(locale==='es'?`Cargando ${file.name}…`:`Uploading ${file.name}…`);const up=await supabase.storage.from('el-molino-files').upload(path,file,{contentType:mime,upsert:false});if(up.error)return flash(t('Could not upload that file.','No se pudo cargar ese archivo.'));const kind=mime.startsWith('image/')?'photo':mime.startsWith('video/')?'video':mime.startsWith('audio/')?'audio':mime.includes('spreadsheet')||file.name.toLowerCase().endsWith('.csv')?'spreadsheet':mime==='application/pdf'?'document':'file';const {data,error}=await supabase.from('files').insert({location_id:profile.location_id,uploaded_by:u.user.id,file_name:file.name.slice(0,255),mime_type:mime,size_bytes:file.size,storage_bucket:'el-molino-files',storage_path:path,kind,title:file.name.slice(0,255)}).select('id').single();if(error){await supabase.storage.from('el-molino-files').remove([path]);return flash(t('File metadata could not be saved, so the upload was rolled back.','No se pudieron guardar los metadatos, así que se revirtió la carga.'))}await logActivity('uploaded','file',data.id,`Uploaded ${file.name.slice(0,255)}`);await loadAll();flash(t('Upload complete.','Carga completada.'))}finally{setUploadBusy(false)}}
  async function openFile(row:FileRow){const popup=window.open('about:blank','_blank');const {data,error}=await supabase.storage.from('el-molino-files').createSignedUrl(row.storage_path,300);if(error||!data?.signedUrl){popup?.close();return flash(t('Could not open that file.','No se pudo abrir ese archivo.'))}if(popup){popup.opener=null;popup.location.replace(data.signedUrl)}else flash(t('Your browser blocked the file window. Allow pop-ups for this app to open files.','Tu navegador bloqueó la ventana del archivo. Permite ventanas emergentes para abrir archivos.'))}
  async function markNotice(n:Notice){if(!n.read_at){const {error}=await supabase.from('notifications').update({read_at:new Date().toISOString()}).eq('id',n.id).is('read_at',null);if(!error){setNotices(rows=>rows.map(x=>x.id===n.id?{...x,read_at:new Date().toISOString()}:x));setUnreadTotal(x=>Math.max(0,x-1));}}setShowNotices(false);if(n.href)window.location.href=safeInternalHref(n.href,'/');else await loadAll();}

  if(!ready)return <FullLoader />;
  if(!signedIn)return <AuthScreen {...{email,setEmail,password,setPassword,fullName,setFullName,authMode,setAuthMode,authBusy,message,auth,forgotPassword}} />;

  return <div className="app-shell">
    {!online&&<div className="offline-banner"><WifiOff size={15}/> {t('Offline — reconnect to load restaurant data. Changes require a connection.','Sin conexión: vuelve a conectarte para cargar datos del restaurante. Los cambios requieren conexión.')}</div>}
    <header className="topbar">
      <div><div className="brand-kicker">El Molino Taqueria</div><div className="brand-title">Johns Island</div></div>
      <div className="top-actions">
        <LanguageToggle compact/>
        <button className="round-button" aria-label={t('Search','Buscar')} onClick={()=>setShowSearch(true)}><Search size={19}/></button>
        <button className="round-button badge-button" aria-label={`${t('Notifications','Notificaciones')}${unreadCount?`, ${unreadCount} ${t('unread','sin leer')}`:''}`} onClick={()=>setShowNotices(true)}><Bell size={19}/>{unreadCount>0&&<span className="badge-count">{unreadCount>9?'9+':unreadCount}</span>}</button>
        <button className="avatar" aria-label={t('Account','Cuenta')} onClick={()=>setShowAccount(true)}>{(profile?.full_name||'D').slice(0,1).toUpperCase()}</button>
      </div>
    </header>
    <main className="page" aria-busy={loading}>
      {message&&<div className="toast-message" role="status">{message}</div>}
      {loading&&<div className="inline-loading"><Loader2 className="spin" size={16}/> {t('Syncing…','Sincronizando…')}</div>}
      {tab==='home'&&<HomeView profile={profile} tasks={openTasks} activity={activity} setTab={setTab} toggleTask={toggleTask} taskBusy={taskBusy}/>} 
      {tab==='operations'&&<OperationsView canManage={canManage} stations={stations} selectedStation={selectedStation} setSelectedStation={setSelectedStation} procedureTitle={procedureTitle} setProcedureTitle={setProcedureTitle} procedureDescription={procedureDescription} setProcedureDescription={setProcedureDescription} procedures={procedures} createProcedure={createProcedure} tasks={tasks} taskTitle={taskTitle} setTaskTitle={setTaskTitle} taskDue={taskDue} setTaskDue={setTaskDue} createTask={createTask} toggleTask={toggleTask} taskBusy={taskBusy} writeBusy={writeBusy}/>} 
      {tab==='team'&&<TeamView canManage={canManage} employeeName={employeeName} setEmployeeName={setEmployeeName} employeePhone={employeePhone} setEmployeePhone={setEmployeePhone} employees={employees} roles={roles} createEmployee={createEmployee} writeBusy={writeBusy}/>} 
      {tab==='ai'&&<AIView profile={profile} knowledge={knowledge} procedures={procedures}/>} 
      {tab==='more'&&<MoreView section={moreSection} setSection={setMoreSection} canManage={canManage} stations={stations} stationName={stationName} setStationName={setStationName} stationDescription={stationDescription} setStationDescription={setStationDescription} selectedStation={selectedStation} setSelectedStation={setSelectedStation} knowledgeTitle={knowledgeTitle} setKnowledgeTitle={setKnowledgeTitle} knowledgeContent={knowledgeContent} setKnowledgeContent={setKnowledgeContent} knowledge={knowledge} createStation={createStation} createKnowledge={createKnowledge} approveKnowledge={approveKnowledge} softDeleteKnowledge={softDeleteKnowledge} files={files} uploadFile={uploadFile} openFile={openFile} activity={activity} prefs={prefs} updatePrefs={updatePrefs} profile={profile} writeBusy={writeBusy} uploadBusy={uploadBusy}/>} 
    </main>
    <nav className="tabs" aria-label={t('Primary navigation','Navegación principal')}>
      <TabButton label={t('Today','Hoy')} active={tab==='home'} onClick={()=>setTab('home')} icon={<Home size={19}/>}/>
      <TabButton label={t('Work','Trabajo')} active={tab==='operations'} onClick={()=>setTab('operations')} icon={<ClipboardCheck size={19}/>}/>
      <TabButton label={t('Team','Equipo')} active={tab==='team'} onClick={()=>setTab('team')} icon={<Users size={19}/>}/>
      <TabButton label={t('Ask AI','Preguntar a IA')} active={tab==='ai'} onClick={()=>setTab('ai')} icon={<Bot size={19}/>}/>
      <TabButton label={t('More','Más')} active={tab==='more'} onClick={()=>{setTab('more');setMoreSection('root')}} icon={<MoreHorizontal size={19}/>}/>
    </nav>
    {showSearch&&<SearchSheet onClose={()=>setShowSearch(false)}/>} 
    {showNotices&&<NotificationSheet notices={notices} onClose={()=>setShowNotices(false)} onOpen={markNotice}/>} 
    {showAccount&&<AccountSheet profile={profile} email={userEmail} onClose={()=>setShowAccount(false)} updateName={updateName} onSignOut={()=>supabase.auth.signOut()}/>} 
    {showOnboarding&&<Onboarding onDone={()=>{localStorage.setItem('elmolino_onboarded','1');setShowOnboarding(false)}}/>}
  </div>;
}

function AuthScreen(p:any){const {t}=useRootT();return <main className="auth-wrap"><div className="auth-card"><div className="brand-kicker">Johns Island</div><LanguageToggle/><h1>El Molino Ops</h1><p>{t('Private restaurant workspace. New accounts require a current invitation.','Espacio privado del restaurante. Las cuentas nuevas requieren una invitación vigente.')}</p><form className="form" onSubmit={p.auth}>{p.authMode==='signup'&&<div className="field"><label>{t('Name','Nombre')}</label><input className="input" autoComplete="name" maxLength={120} value={p.fullName} onChange={(e:any)=>p.setFullName(e.target.value)} required/></div>}<div className="field"><label>{t('Email','Correo electrónico')}</label><input className="input" type="email" autoComplete="email" maxLength={254} value={p.email} onChange={(e:any)=>p.setEmail(e.target.value)} required/></div><div className="field"><label>{t('Password','Contraseña')}</label><input className="input" type="password" autoComplete={p.authMode==='signin'?'current-password':'new-password'} minLength={p.authMode==='signup'?10:8} maxLength={256} value={p.password} onChange={(e:any)=>p.setPassword(e.target.value)} required/>{p.authMode==='signup'&&<small>{t('At least 10 characters with letters and a number.','Al menos 10 caracteres con letras y un número.')}</small>}</div><div className="remember-row"><Check size={15}/><span>{t('Remember me on this device','Recordarme en este dispositivo')}</span></div><button className="btn" disabled={p.authBusy}>{p.authBusy?<><Loader2 className="spin" size={16}/> {t('Working…','Procesando…')}</>:p.authMode==='signup'?t('Create invited account','Crear cuenta invitada'):t('Sign in','Iniciar sesión')}</button></form>{p.message&&<div className="notice" style={{marginTop:12}} role="status">{p.message}</div>}<div className="auth-links"><button onClick={()=>p.setAuthMode(p.authMode==='signup'?'signin':'signup')}>{p.authMode==='signup'?t('I already have an account','Ya tengo una cuenta'):t('Create invited account','Crear cuenta invitada')}</button>{p.authMode==='signin'&&<button onClick={p.forgotPassword}>{t('Forgot password?','¿Olvidaste tu contraseña?')}</button>}</div></div></main>}

function HomeView({profile,tasks,activity,setTab,toggleTask,taskBusy}:{profile:Profile|null;tasks:Task[];activity:ActivityRow[];setTab:(t:Tab)=>void;toggleTask:(t:Task)=>void;taskBusy:boolean}){const {locale,t}=useRootT();const hr=new Date().getHours();const greeting=hr<12?t('Good morning','Buenos días'):hr<17?t('Good afternoon','Buenas tardes'):t('Good evening','Buenas noches');return <><section className="hero home-hero"><div className="brand-kicker hero-kicker">{rootToken(profile?.app_role||'member',locale)}</div><h1>{greeting}.</h1><p>{t('Your day at Johns Island — work first, system details stay out of the way.','Tu día en Johns Island: primero el trabajo; los detalles del sistema quedan aparte.')}</p><button className="hero-action" onClick={()=>setTab('ai')}><Sparkles size={17}/> {t('Ask El Molino','Preguntar a El Molino')}</button></section><div className="section-title"><h2>{t('Today','Hoy')}</h2><span>{tasks.length} {t('open','abiertas')}</span></div>{tasks.length?<div className="list">{tasks.slice(0,5).map(t=><button disabled={taskBusy} className="list-item" key={t.id} onClick={()=>toggleTask(t)}><div className="icon-wrap">{t.status==='done'?<CheckCircle2 size={18}/>:<Circle size={18}/>}</div><div className="list-main"><b>{t.title}</b><small>{formatDue(t.due_at,locale)} · {rootToken(t.priority,locale)}</small></div><ChevronRight size={17} className="muted-icon"/></button>)}</div>:<EmptyState icon={<CheckCircle2 size={24}/>} title={t('Nothing assigned yet','Aún no tienes asignaciones')} body={t('Tasks, checklists and shift duties will appear here.','Aquí aparecerán tareas, listas y deberes del turno.')}/>}<div className="section-title"><h2>{t('Quick actions','Acciones rápidas')}</h2><span>{t('run the shift','dirige el turno')}</span></div><div className="quick-grid"><button className="quick-card" onClick={()=>setTab('operations')}><ClipboardCheck/><b>{t('Work','Trabajo')}</b><small>{t('Tasks & procedures','Tareas y procedimientos')}</small></button><button className="quick-card" onClick={()=>setTab('team')}><Users/><b>{t('Team','Equipo')}</b><small>{t('People & training','Personal y capacitación')}</small></button><a className="quick-card" href="/menu"><MenuIcon/><b>{t('Menu','Menú')}</b><small>{t('Catalog','Catálogo')}</small></a><button className="quick-card" onClick={()=>setTab('ai')}><Bot/><b>{t('Ask AI','Preguntar a IA')}</b><small>{t('Internal + El Molino web','Información interna y web de El Molino')}</small></button></div>{activity.length>0&&<><div className="section-title"><h2>{t('Recent','Reciente')}</h2><span>{t('activity','actividad')}</span></div><div className="list">{activity.slice(0,4).map(a=><div className="list-item" key={a.id}><div className="icon-wrap"><History size={17}/></div><div className="list-main"><b>{a.summary||a.action}</b><small>{timeAgo(a.created_at,locale)}</small></div></div>)}</div></>}</>}

function OperationsView(p:any){const {locale,t}=useRootT();return <><PageHeading title={t('Work','Trabajo')} subtitle={t('Tasks, procedures and repeatable shift execution','Tareas, procedimientos y ejecución repetible del turno')}/><div className="segmented-summary"><div><strong>{p.tasks.filter((t:Task)=>!['done','cancelled'].includes(t.status)).length}</strong><span>{t('Open tasks','Tareas abiertas')}</span></div><div><strong>{p.procedures.length}</strong><span>{t('Procedures','Procedimientos')}</span></div></div>{p.canManage&&<div className="card" style={{marginBottom:12}}><h3>{t('Quick task','Tarea rápida')}</h3><form className="form" onSubmit={p.createTask}><input className="input" maxLength={200} placeholder={t('What needs to get done?','¿Qué hay que hacer?')} value={p.taskTitle} onChange={(e:any)=>p.setTaskTitle(e.target.value)} required/><input className="input" type="datetime-local" value={p.taskDue} onChange={(e:any)=>p.setTaskDue(e.target.value)}/><button className="btn" disabled={p.taskBusy}><Plus size={16}/> {t('Add task','Agregar tarea')}</button></form></div>}<div className="section-title"><h2>{t('Tasks','Tareas')}</h2><span>{t('tap to complete','toca para completar')}</span></div>{p.tasks.length?<div className="list">{p.tasks.map((t:Task)=><button disabled={p.taskBusy} className={`list-item ${t.status==='done'?'completed-row':''}`} key={t.id} onClick={()=>p.toggleTask(t)}><div className="icon-wrap">{t.status==='done'?<CheckCircle2 size={18}/>:<Circle size={18}/>}</div><div className="list-main"><b>{t.title}</b><small>{formatDue(t.due_at,locale)} · {rootToken(t.priority,locale)}</small></div><span className="status">{rootToken(t.status,locale)}</span></button>)}</div>:<EmptyState icon={<ClipboardCheck/>} title={t('No tasks yet','Aún no hay tareas')} body={t('Create a task or later generate duties from approved procedures.','Crea una tarea o genera deberes desde procedimientos aprobados.')}/>}{p.canManage&&<><div className="section-title"><h2>{t('Procedure builder','Creador de procedimientos')}</h2><span>{t('manager','gerencia')}</span></div><div className="card"><form className="form" onSubmit={p.createProcedure}><select className="select" value={p.selectedStation} onChange={(e:any)=>p.setSelectedStation(e.target.value)}><option value="">{t('General / no station','General / sin estación')}</option>{p.stations.map((s:Station)=><option key={s.id} value={s.id}>{s.name}</option>)}</select><input className="input" maxLength={200} placeholder={t('Procedure title','Título del procedimiento')} value={p.procedureTitle} onChange={(e:any)=>p.setProcedureTitle(e.target.value)} required/><textarea className="textarea" maxLength={8000} placeholder={t('Describe the process','Describe el proceso')} value={p.procedureDescription} onChange={(e:any)=>p.setProcedureDescription(e.target.value)}/><button className="btn" disabled={p.writeBusy}>{t('Save procedure draft','Guardar borrador del procedimiento')}</button></form></div></>}<div className="section-title"><h2>{t('Procedures','Procedimientos')}</h2><span>{p.procedures.length}</span></div>{p.procedures.length?<div className="list">{p.procedures.map((x:Procedure)=><div className="list-item" key={x.id}><div className="icon-wrap"><ClipboardCheck size={18}/></div><div className="list-main"><b>{x.title}</b><small>{x.description||t('No description yet','Sin descripción todavía')}</small></div><span className="status">{rootToken(x.status,locale)}</span></div>)}</div>:<EmptyState icon={<FileText/>} title={t('No procedures yet','Aún no hay procedimientos')} body={t('Approved restaurant knowledge can be turned into procedures here.','Aquí puedes convertir conocimiento aprobado del restaurante en procedimientos.')}/>}</>}

function TeamView(p:any){const {locale,t}=useRootT();return <><PageHeading title={t('Team','Equipo')} subtitle={t('People, roles and training records','Personal, puestos y registros de capacitación')}/>{p.canManage&&<div className="card" style={{marginBottom:14}}><h3>{t('Add team member','Agregar integrante del equipo')}</h3><form className="form" onSubmit={p.createEmployee}><input className="input" maxLength={200} placeholder={t('Full name','Nombre completo')} value={p.employeeName} onChange={(e:any)=>p.setEmployeeName(e.target.value)} required/><input className="input" inputMode="tel" maxLength={80} placeholder={t('Phone','Teléfono')} value={p.employeePhone} onChange={(e:any)=>p.setEmployeePhone(e.target.value)}/><button className="btn" disabled={p.writeBusy}><UserPlus size={16}/> {t('Add employee','Agregar empleado')}</button></form></div>}<div className="section-title"><h2>{t('Roster','Plantilla')}</h2><span>{p.employees.length} {t('people','personas')}</span></div>{p.employees.length?<div className="list">{p.employees.map((e:Employee)=><div className="list-item" key={e.id}><div className="person-avatar">{e.full_name.slice(0,1).toUpperCase()}</div><div className="list-main"><b>{e.full_name}</b><small>{e.phone||t('No phone added','Sin teléfono')}{e.start_date?` · ${t('Started','Inicio')} ${new Date(e.start_date).toLocaleDateString(locale==='es'?'es-US':'en-US')}`:''}</small></div><span className="status">{e.active?t('Active','Activo'):t('Inactive','Inactivo')}</span></div>)}</div>:<EmptyState icon={<Users/>} title={t('No team added yet','Aún no se agregó el equipo')} body={t('Add the roster first; roles, training and assignments build on it.','Agrega primero la plantilla; los puestos, la capacitación y las asignaciones dependen de ella.')}/>}</>}

function AIView({profile,knowledge,procedures}:{profile:Profile|null;knowledge:KnowledgeItem[];procedures:Procedure[]}){
  const {locale,t}=useRootT();
  const [q,setQ]=useState(''),[busy,setBusy]=useState(false),[mode,setMode]=useState<AIMode>('auto');
  const [convos,setConvos]=useState<AIConversation[]>([]),[current,setCurrent]=useState<string|null>(null),[msgs,setMsgs]=useState<AIMessage[]>([]),[showHistory,setShowHistory]=useState(false);
  useEffect(()=>{void loadConvos()},[]);
  async function loadConvos(){const {data}=await supabase.from('ai_conversations').select('id,title,source_mode,updated_at').eq('archived',false).order('updated_at',{ascending:false}).limit(30);setConvos((data??[]) as AIConversation[]);}
  async function openConvo(id:string){setCurrent(id);setShowHistory(false);const {data}=await supabase.from('ai_messages').select('id,role,content,source_label,feedback,created_at').eq('conversation_id',id).in('role',['user','assistant']).order('created_at');setMsgs((data??[]) as AIMessage[]);const c=convos.find(x=>x.id===id);if(c)setMode(c.source_mode);}
  function newConvo(){setCurrent(null);setMsgs([]);setQ('');setShowHistory(false);}
  async function ask(e:FormEvent){e.preventDefault();const question=q.trim();if(!question||!profile?.location_id)return;setBusy(true);setQ('');try{const {data:u}=await supabase.auth.getUser();if(!u.user)return;let id=current;if(!id){const {data:c,error}=await supabase.from('ai_conversations').insert({location_id:profile.location_id,user_id:u.user.id,title:question.slice(0,60),source_mode:mode}).select('id').single();if(error)throw error;id=c.id;setCurrent(id);await loadConvos();}const optimistic:AIMessage={id:`local-${Date.now()}`,role:'user',content:question,source_label:null,feedback:null,created_at:new Date().toISOString()};setMsgs(m=>[...m,optimistic]);await supabase.from('ai_messages').insert({conversation_id:id,role:'user',content:question});const r=await fetch('/api/ask',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({question,mode,knowledge,procedures})});const j=await r.json();const text=j.answer||t('I could not answer that.','No pude responder eso.');const source=j.source||t('Assistant','Asistente');const {data:am}=await supabase.from('ai_messages').insert({conversation_id:id,role:'assistant',content:text,source_label:source}).select('id,role,content,source_label,feedback,created_at').single();await supabase.from('ai_conversations').update({source_mode:mode,updated_at:new Date().toISOString()}).eq('id',id);if(am)setMsgs(m=>[...m,am as AIMessage]);await loadConvos();}catch(err){setMsgs(m=>[...m,{id:`err-${Date.now()}`,role:'assistant',content:err instanceof Error?err.message:t('The assistant could not connect.','El asistente no pudo conectarse.'),source_label:t('Assistant error','Error del asistente'),feedback:null,created_at:new Date().toISOString()}]);}finally{setBusy(false);}}
  async function feedback(m:AIMessage,val:1|-1){if(m.id.startsWith('local')||m.id.startsWith('err'))return;await supabase.from('ai_messages').update({feedback:val}).eq('id',m.id);setMsgs(rows=>rows.map(x=>x.id===m.id?{...x,feedback:val}:x));}
  return <><div className="ai-header"><div><h2>{t('Ask El Molino','Preguntar a El Molino')}</h2><p>{t('Internal knowledge first. Web access is restricted to El Molino.','Primero se usa el conocimiento interno. El acceso web está restringido a El Molino.')}</p></div><button className="round-button" aria-label={t('Conversation history','Historial de conversación')} onClick={()=>setShowHistory(!showHistory)}><History size={19}/></button></div>{showHistory&&<div className="card history-card"><button className="btn secondary" onClick={newConvo}><Plus size={15}/> {t('New conversation','Nueva conversación')}</button><div className="history-list">{convos.map(c=><button key={c.id} onClick={()=>openConvo(c.id)}><b>{c.title}</b><small>{rootToken(c.source_mode,locale)} · {timeAgo(c.updated_at,locale)}</small></button>)}{!convos.length&&<small>{t('No previous conversations.','No hay conversaciones anteriores.')}</small>}</div></div>}<div className="source-switch">{(['auto','internal','web'] as AIMode[]).map(m=><button key={m} className={mode===m?'active':''} onClick={()=>setMode(m)}>{m==='auto'?t('Auto','Automático'):m==='internal'?t('Internal','Interno'):t('El Molino Web','Web de El Molino')}</button>)}</div><div className="chat"><div className="assistant-intro"><Sparkles size={18}/><div><b>{t('What do you need?','¿Qué necesitas?')}</b><span>{t('I can explain what I can do even before the restaurant has taught me a specific procedure.','Puedo explicar mis capacidades incluso antes de que el restaurante me enseñe un procedimiento específico.')}</span></div></div>{msgs.map(m=><div className={`chat-row ${m.role}`} key={m.id}><div className="bubble">{m.source_label&&m.role==='assistant'&&<small className="source-label">{m.source_label}</small>}<div>{m.content}</div>{m.role==='assistant'&&<div className="feedback-row"><button aria-label={t('Helpful','Útil')} className={m.feedback===1?'selected':''} onClick={()=>feedback(m,1)}>{t('Helpful','Útil')}</button><button aria-label={t('Not helpful','No útil')} className={m.feedback===-1?'selected':''} onClick={()=>feedback(m,-1)}>{t('Needs work','Necesita mejorar')}</button></div>}</div></div>)}{busy&&<div className="chat-row assistant"><div className="bubble"><Loader2 className="spin" size={17}/> {t('Thinking…','Pensando…')}</div></div>}</div><form className="ai-composer" onSubmit={ask}><textarea value={q} onChange={e=>setQ(e.target.value)} placeholder={t('Ask about El Molino…','Pregunta sobre El Molino…')} aria-label={t('Ask El Molino AI','Preguntar a la IA de El Molino')}/><button disabled={busy||!q.trim()}><Sparkles size={18}/></button></form></>}

function MoreView(p:any){const {t}=useRootT();if(p.section!=='root')return <MoreDetail {...p}/>;return <><PageHeading title={t('More','Más')} subtitle={t('Tools and administration that stay out of your main workflow','Herramientas y administración fuera de tu flujo principal')}/><div className="settings-list"><MoreLink icon={<BookOpen/>} title={t('Knowledge Studio','Estudio de Conocimiento')} body={t('Stations, internal knowledge and public research','Estaciones, conocimiento interno e investigación pública')} onClick={()=>p.setSection('knowledge')}/><a className="settings-row" href="/manager"><span className="settings-icon"><Activity/></span><span><b>{t('Manager Dashboard','Panel de Gerencia')}</b><small>{t('GM/MOD overview and operational exceptions','Resumen de GM/MOD y excepciones operativas')}</small></span><ChevronRight/></a><a className="settings-row" href="/performance"><span className="settings-icon"><Activity/></span><span><b>{t('Performance','Rendimiento')}</b><small>{t('Sales, labor, Toast imports and weekly trends','Ventas, mano de obra, importaciones de Toast y tendencias semanales')}</small></span><ChevronRight/></a><a className="settings-row" href="/logbook"><span className="settings-icon"><History/></span><span><b>{t('Manager Logbook','Bitácora de Gerencia')}</b><small>{t('MOD handoffs, guest issues, 86s and follow-ups','Entregas de MOD, asuntos de clientes, agotados y seguimientos')}</small></span><ChevronRight/></a><a className="settings-row" href="/schedule"><span className="settings-icon"><Users/></span><span><b>{t('Schedule','Horario')}</b><small>{t('Shifts, time off, call-outs and coverage','Turnos, tiempo libre, ausencias y cobertura')}</small></span><ChevronRight/></a><a className="settings-row" href="/inventory"><span className="settings-icon"><FileText/></span><span><b>{t('Inventory & Food Cost','Inventario y Costo de Alimentos')}</b><small>{t('Counts, pars, ordering, waste and recipe cost','Conteos, niveles par, pedidos, desperdicio y costo de recetas')}</small></span><ChevronRight/></a><a className="settings-row" href="/safety"><span className="settings-icon"><ShieldCheck/></span><span><b>{t('Food Safety','Seguridad Alimentaria')}</b><small>{t('Opening/closing checks, temperatures and corrective actions','Revisiones de apertura/cierre, temperaturas y acciones correctivas')}</small></span><ChevronRight/></a><a className="settings-row" href="/maintenance"><span className="settings-icon"><Settings/></span><span><b>{t('Maintenance','Mantenimiento')}</b><small>{t('Equipment, repair tickets and service history','Equipos, solicitudes de reparación e historial de servicio')}</small></span><ChevronRight/></a><a className="settings-row" href="/training"><span className="settings-icon"><Users/></span><span><b>{t('Training & Certifications','Capacitación y Certificaciones')}</b><small>{t('Assignments, expirations and manager coaching','Asignaciones, vencimientos y orientación de gerencia')}</small></span><ChevronRight/></a><a className="settings-row" href="/incidents"><span className="settings-icon"><ShieldCheck/></span><span><b>{t('Incident Reporting','Reporte de Incidentes')}</b><small>{t('Private safety, injury, conduct and property reports','Reportes privados de seguridad, lesiones, conducta y propiedad')}</small></span><ChevronRight/></a><a className="settings-row" href="/cash"><span className="settings-icon"><KeyRound/></span><span><b>{t('Cash Controls','Controles de Efectivo')}</b><small>{t('Drawer reconciliation, deposits, safe count and over/short','Conciliación de caja, depósitos, conteo de caja fuerte y diferencias')}</small></span><ChevronRight/></a><a className="settings-row" href="/vendors"><span className="settings-icon"><FolderOpen/></span><span><b>{t('Vendors','Proveedores')}</b><small>{t('Contacts, accounts, orders and service history','Contactos, cuentas, pedidos e historial de servicio')}</small></span><ChevronRight/></a><a className="settings-row" href="/menu"><span className="settings-icon"><MenuIcon/></span><span><b>{t('Menu Catalog','Catálogo del Menú')}</b><small>{t('Structured products, categories and prices','Productos, categorías y precios estructurados')}</small></span><ChevronRight/></a><MoreLink icon={<FolderOpen/>} title={t('Files & Media','Archivos y Multimedia')} body={t('Photos, documents, audio, video and spreadsheets','Fotos, documentos, audio, video y hojas de cálculo')} onClick={()=>p.setSection('files')}/><MoreLink icon={<Activity/>} title={t('Activity','Actividad')} body={t('Who changed what and when','Quién cambió qué y cuándo')} onClick={()=>p.setSection('activity')}/><MoreLink icon={<Settings/>} title={t('Settings','Configuración')} body={t('Account, notifications, accessibility and app preferences','Cuenta, notificaciones, accesibilidad y preferencias de la aplicación')} onClick={()=>p.setSection('settings')}/>{p.profile?.app_role==='admin'&&<MoreLink icon={<ShieldCheck/>} title={t('Admin Center','Centro de Administración')} body={t('System data, users and app health','Datos del sistema, usuarios y estado de la aplicación')} onClick={()=>p.setSection('admin')}/>}</div><div className="install-note"><Download size={18}/><div><b>{t('Install as an app','Instalar como aplicación')}</b><small>{t('On iPhone: Share → Add to Home Screen. Your login remains attached to the permanent app URL.','En iPhone: Compartir → Agregar a Inicio. Tu sesión permanece vinculada a la URL permanente de la aplicación.')}</small></div></div></>}

function MoreDetail(p:any){const {t}=useRootT();return <><button className="back-link" onClick={()=>p.setSection('root')}>‹ {t('More','Más')}</button>{p.section==='knowledge'&&<KnowledgeSection {...p}/>} {p.section==='files'&&<FilesSection files={p.files} uploadFile={p.uploadFile} openFile={p.openFile} uploadBusy={p.uploadBusy}/>} {p.section==='activity'&&<ActivitySection rows={p.activity}/>} {p.section==='settings'&&<SettingsSection prefs={p.prefs} updatePrefs={p.updatePrefs}/>} {p.section==='admin'&&<AdminSection knowledge={p.knowledge} stations={p.stations} files={p.files} activity={p.activity}/>}</>}

function KnowledgeSection(p:any){const {locale,t}=useRootT();return <><PageHeading title={t('Knowledge Studio','Estudio de Conocimiento')} subtitle={t('Backend knowledge is managed here, not on the home screen','El conocimiento administrativo se gestiona aquí, no en la pantalla de inicio')}/>{p.canManage&&<><div className="card" style={{marginBottom:12}}><h3>{t('Add kitchen station','Agregar estación de cocina')}</h3><form className="form" onSubmit={p.createStation}><input className="input" maxLength={200} placeholder={t('Station name','Nombre de la estación')} value={p.stationName} onChange={(e:any)=>p.setStationName(e.target.value)} required/><textarea className="textarea" maxLength={2000} placeholder={t('What happens here?','¿Qué sucede aquí?')} value={p.stationDescription} onChange={(e:any)=>p.setStationDescription(e.target.value)}/><button className="btn" disabled={p.writeBusy}>{t('Add station','Agregar estación')}</button></form></div><div className="card" style={{marginBottom:12}}><div className="card-title-row"><h3>{t('Add internal knowledge','Agregar conocimiento interno')}</h3><span className="autosave-label">{t('Draft autosaves','El borrador se guarda automáticamente')}</span></div><form className="form" onSubmit={p.createKnowledge}><select className="select" value={p.selectedStation} onChange={(e:any)=>p.setSelectedStation(e.target.value)}><option value="">{t('General','General')}</option>{p.stations.map((s:Station)=><option key={s.id} value={s.id}>{s.name}</option>)}</select><input className="input" maxLength={200} placeholder={t('Title','Título')} value={p.knowledgeTitle} onChange={(e:any)=>p.setKnowledgeTitle(e.target.value)} required/><textarea className="textarea" maxLength={20000} placeholder={t('Teach the system how El Molino actually does this','Enseña al sistema cómo lo hace realmente El Molino')} value={p.knowledgeContent} onChange={(e:any)=>p.setKnowledgeContent(e.target.value)} required/><button className="btn" disabled={p.writeBusy}>{t('Save draft','Guardar borrador')}</button></form></div></>}<div className="section-title"><h2>{t('Knowledge records','Registros de conocimiento')}</h2><span>{p.knowledge.length}</span></div><div className="list">{p.knowledge.map((k:KnowledgeItem)=><div className="list-item" key={k.id}><div className="icon-wrap">{k.category?.includes('research')?<Globe2 size={18}/>:<BookOpen size={18}/>}</div><div className="list-main"><b>{k.title}</b><small>{rootToken(k.category||'internal',locale)} · {rootToken(k.status,locale)}</small></div><div className="row-actions">{p.canManage&&k.status!=='approved'&&!k.category?.includes('research')&&<button disabled={p.writeBusy} className="mini-action" onClick={()=>p.approveKnowledge(k.id)}>{t('Approve','Aprobar')}</button>}{p.canManage&&<button disabled={p.writeBusy} className="icon-action danger-action" aria-label={t('Move to trash','Mover a la papelera')} onClick={()=>p.softDeleteKnowledge(k.id)}><Trash2 size={16}/></button>}</div></div>)}</div></>}

function FilesSection({files,uploadFile,openFile,uploadBusy}:{files:FileRow[];uploadFile:(f:File)=>void;openFile:(f:FileRow)=>void;uploadBusy:boolean}){const {locale,t}=useRootT();const choose=(e:React.ChangeEvent<HTMLInputElement>)=>{const f=e.target.files?.[0];if(f)void uploadFile(f);e.target.value=''};return <><PageHeading title={t('Files & Media','Archivos y Multimedia')} subtitle={t('Capture the restaurant with photos, documents, video, voice and spreadsheets','Documenta el restaurante con fotos, documentos, video, voz y hojas de cálculo')}/><div className="upload-grid"><label className="upload-tile"><Camera/><b>{t('Take photo','Tomar foto')}</b><small>{t('Camera or photo library','Cámara o fototeca')}</small><input disabled={uploadBusy} hidden type="file" accept="image/*" capture="environment" onChange={choose}/></label><label className="upload-tile"><Mic/><b>{t('Voice / audio','Voz / audio')}</b><small>{t('Upload a recording','Cargar una grabación')}</small><input disabled={uploadBusy} hidden type="file" accept="audio/*" onChange={choose}/></label><label className="upload-tile"><FileText/><b>{t('Document','Documento')}</b><small>{t('PDF, Word, CSV or spreadsheet','PDF, Word, CSV u hoja de cálculo')}</small><input disabled={uploadBusy} hidden type="file" accept=".pdf,.doc,.docx,.csv,.xlsx,.txt" onChange={choose}/></label><label className="upload-tile"><Upload/><b>{t('Supported file','Archivo compatible')}</b><small>{t('Up to 50 MB','Hasta 50 MB')}</small><input disabled={uploadBusy} hidden type="file" accept=".pdf,.docx,.csv,.xlsx,.txt,image/*,video/mp4,audio/*" onChange={choose}/></label></div><div className="section-title"><h2>{t('Library','Biblioteca')}</h2><span>{files.length}</span></div>{files.length?<div className="list">{files.map(f=><button disabled={uploadBusy} className="list-item" key={f.id} onClick={()=>openFile(f)}><div className="icon-wrap"><FileText size={18}/></div><div className="list-main"><b>{f.title||f.file_name}</b><small>{rootToken(f.kind,locale)} · {formatBytes(f.size_bytes,locale)}</small></div><ChevronRight size={17}/></button>)}</div>:<EmptyState icon={<FolderOpen/>} title={t('No files yet','Aún no hay archivos')} body={t('Photos, manuals, voice notes and restaurant documents will live here.','Aquí estarán fotos, manuales, notas de voz y documentos del restaurante.')}/>}</>}

function ActivitySection({rows}:{rows:ActivityRow[]}){const {locale,t}=useRootT();return <><PageHeading title={t('Activity','Actividad')} subtitle={t('An audit trail of important changes','Un historial de auditoría de cambios importantes')}/>{rows.length?<div className="timeline">{rows.map(r=><div className="timeline-row" key={r.id}><div className="timeline-dot"/><div><b>{r.summary||r.action}</b><small>{rootToken(r.entity_type||'system',locale)} · {new Date(r.created_at).toLocaleString(locale==='es'?'es-US':'en-US')}</small></div></div>)}</div>:<EmptyState icon={<Activity/>} title={t('No recorded activity yet','Aún no hay actividad registrada')} body={t('New edits, approvals, uploads and assignments will appear here.','Aquí aparecerán ediciones, aprobaciones, cargas y asignaciones nuevas.')}/>}</>}

function SettingsSection({prefs,updatePrefs}:{prefs:Prefs;updatePrefs:(p:Partial<Prefs>)=>void}){const {t}=useRootT();return <><PageHeading title={t('Settings','Configuración')} subtitle={t('Personalize how the app behaves on this device','Personaliza el comportamiento de la aplicación en este dispositivo')}/><div className="settings-card"><div className="setting-row"><div><b>{t('Language','Idioma')}</b><small>{t('Choose English or Spanish for system interface copy','Elige inglés o español para la interfaz del sistema')}</small></div><LanguageToggle compact/></div><SettingToggle title={t('Remember email','Recordar correo electrónico')} body={t('Keep your email filled in if you ever need to sign in again','Mantén tu correo listo si necesitas iniciar sesión de nuevo')} value={prefs.remember_email} onChange={v=>updatePrefs({remember_email:v})}/><SettingToggle title={t('In-app notifications','Notificaciones en la aplicación')} body={t('Show operational notifications inside the app','Muestra notificaciones operativas dentro de la aplicación')} value={prefs.in_app_notifications} onChange={v=>updatePrefs({in_app_notifications:v})}/><SettingToggle title={t('Email notifications','Notificaciones por correo')} body={t('Allow email delivery when notification delivery is enabled','Permite la entrega por correo cuando las notificaciones están habilitadas')} value={prefs.email_notifications} onChange={v=>updatePrefs({email_notifications:v})}/><SettingToggle title={t('Push notifications','Notificaciones push')} body={t('Allow device push delivery when configured','Permite notificaciones push del dispositivo cuando estén configuradas')} value={prefs.push_notifications} onChange={v=>updatePrefs({push_notifications:v})}/><SettingToggle title={t('Reduced motion','Movimiento reducido')} body={t('Minimize animation and movement','Minimiza las animaciones y el movimiento')} value={prefs.reduced_motion} onChange={v=>updatePrefs({reduced_motion:v})}/><SettingToggle title={t('Compact mode','Modo compacto')} body={t('Fit more information on larger screens','Muestra más información en pantallas grandes')} value={prefs.compact_mode} onChange={v=>updatePrefs({compact_mode:v})}/><div className="setting-row"><div><b>{t('Appearance','Apariencia')}</b><small>{t('Use device setting, light or dark','Usa la configuración del dispositivo, claro u oscuro')}</small></div><select className="select compact-select" value={prefs.theme} onChange={e=>updatePrefs({theme:e.target.value as Prefs['theme']})}><option value="system">{t('System','Sistema')}</option><option value="light">{t('Light','Claro')}</option><option value="dark">{t('Dark','Oscuro')}</option></select></div></div></>}

function AdminSection({knowledge,stations,files,activity}:{knowledge:KnowledgeItem[];stations:Station[];files:FileRow[];activity:ActivityRow[]}){const {t}=useRootT();return <><PageHeading title={t('Admin Center','Centro de Administración')} subtitle={t('System controls and health stay here','Los controles y el estado del sistema se encuentran aquí')}/><div className="metric-grid"><Metric label={t('Knowledge','Conocimiento')} value={knowledge.length}/><Metric label={t('Stations','Estaciones')} value={stations.length}/><Metric label={t('Files','Archivos')} value={files.length}/><Metric label={t('Audit events','Eventos de auditoría')} value={activity.length}/></div><div className="notice" style={{marginTop:14}}>{t('User invitations, fine-grained permissions, backups, integrations, error telemetry and system exports are available through the dedicated administration tools.','Las invitaciones, permisos detallados, respaldos, integraciones, telemetría de errores y exportaciones están disponibles en las herramientas de administración.')}</div></>}

function SearchSheet({onClose}:{onClose:()=>void}){const {locale,t}=useRootT();const [q,setQ]=useState(''),[rows,setRows]=useState<SearchResult[]>([]),[busy,setBusy]=useState(false);const seq=useRef(0);useEffect(()=>{const request=++seq.current;const id=setTimeout(async()=>{if(q.trim().length<2){setRows([]);setBusy(false);return;}setBusy(true);const {data,error}=await supabase.rpc('global_search',{search_text:q.trim(),result_limit:30});if(request!==seq.current)return;setRows(error?[]:(data??[]) as SearchResult[]);setBusy(false);},220);return()=>{clearTimeout(id);seq.current++}},[q]);return <div className="sheet-backdrop" role="dialog" aria-modal="true" aria-labelledby="root-search-title"><div className="sheet full-sheet"><div className="sheet-head"><h2 id="root-search-title">{t('Search everything','Buscar en todo')}</h2><button className="round-button" onClick={onClose} aria-label={t('Close search','Cerrar búsqueda')}><X/></button></div><div className="search-field"><Search size={19}/><input autoFocus maxLength={120} aria-label={t('Search restaurant workspace','Buscar en el espacio del restaurante')} placeholder={t('People, procedures, menu, knowledge…','Personas, procedimientos, menú, conocimiento…')} value={q} onChange={e=>setQ(e.target.value)}/>{busy&&<Loader2 className="spin" size={17}/>}</div><div className="list search-results">{rows.map(r=><a className="list-item" key={`${r.entity_type}-${r.entity_id}`} href={safeInternalHref(r.href,'/')}><div className="icon-wrap"><Search size={17}/></div><div className="list-main"><b>{r.title}</b><small>{rootToken(r.entity_type,locale)} · {r.subtitle}</small></div><ChevronRight size={17}/></a>)}{q.length>=2&&!busy&&!rows.length&&<EmptyState icon={<Search/>} title={t('No matches','Sin resultados')} body={t('Try a shorter or different search.','Prueba una búsqueda más corta o diferente.')}/>}</div></div></div>}

function NotificationSheet({notices,onClose,onOpen}:{notices:Notice[];onClose:()=>void;onOpen:(n:Notice)=>void}){const {locale,t}=useRootT();return <div className="sheet-backdrop" role="dialog" aria-modal="true" aria-labelledby="notifications-title"><div className="sheet"><div className="sheet-head"><h2 id="notifications-title">{t('Notifications','Notificaciones')}</h2><button className="round-button" onClick={onClose} aria-label={t('Close notifications','Cerrar notificaciones')}><X/></button></div>{notices.length?<div className="list">{notices.map(n=><button className={`list-item ${!n.read_at?'unread':''}`} key={n.id} onClick={()=>onOpen(n)}><div className="icon-wrap"><Bell size={17}/></div><div className="list-main"><b>{n.title}</b><small>{n.body||timeAgo(n.created_at,locale)}</small></div>{!n.read_at&&<span className="unread-dot"/>}</button>)}</div>:<EmptyState icon={<Bell/>} title={t("You're caught up",'Estás al día')} body={t('New assignments and important updates will appear here.','Aquí aparecerán asignaciones nuevas y actualizaciones importantes.')}/>}</div></div>}

function AccountSheet({profile,email,onClose,updateName,onSignOut}:{profile:Profile|null;email:string;onClose:()=>void;updateName:()=>void;onSignOut:()=>void}){const {locale,t}=useRootT();return <div className="sheet-backdrop" role="dialog" aria-modal="true" aria-labelledby="account-sheet-title"><div className="sheet"><div className="sheet-head"><h2 id="account-sheet-title">{t('Account','Cuenta')}</h2><button className="round-button" onClick={onClose} aria-label={t('Close account','Cerrar cuenta')}><X/></button></div><div className="account-hero"><div className="large-avatar">{(profile?.full_name||'D').slice(0,1).toUpperCase()}</div><div><b>{profile?.full_name||t('Account','Cuenta')}</b><small>{email}</small><span className="status">{rootToken(profile?.app_role||'member',locale)}</span></div></div><button className="settings-row button-row" onClick={updateName}><span className="settings-icon"><CircleUserRound/></span><span><b>{t('Edit profile','Editar perfil')}</b><small>{t('Change your display name','Cambiar tu nombre visible')}</small></span><ChevronRight/></button><button className="settings-row button-row" onClick={onSignOut}><span className="settings-icon"><LogOut/></span><span><b>{t('Sign out','Cerrar sesión')}</b><small>{t('This is the action that ends your remembered session','Esta acción termina tu sesión recordada')}</small></span><ChevronRight/></button></div></div>}

function Onboarding({onDone}:{onDone:()=>void}){const {t}=useRootT();const [step,setStep]=useState(0);const slides=[{icon:<Home/>,title:t('Your work, not the database','Tu trabajo, no la base de datos'),body:t('Today stays focused on what you need to run the shift. Research and system records stay in More.','Hoy se enfoca en lo necesario para dirigir el turno. La investigación y los registros del sistema están en Más.')},{icon:<Bot/>,title:t('Ask El Molino','Preguntar a El Molino'),body:t('Auto uses internal knowledge first. El Molino Web is restricted to restaurant-related public information.','Automático usa primero el conocimiento interno. La Web de El Molino se limita a información pública del restaurante.')},{icon:<Camera/>,title:t('Teach it over time','Enséñale con el tiempo'),body:t('Capture photos, documents and real procedures. Draft knowledge stays separate until a manager approves it.','Captura fotos, documentos y procedimientos reales. Los borradores quedan separados hasta que gerencia los apruebe.')}];const s=slides[step];return <div className="onboard-backdrop"><div className="onboard-card"><div className="onboard-icon">{s.icon}</div><h2>{s.title}</h2><p>{s.body}</p><div className="dots">{slides.map((_,i)=><span key={i} className={i===step?'active':''}/>)}</div><button className="btn" onClick={()=>step<slides.length-1?setStep(step+1):onDone()}>{step<slides.length-1?t('Continue','Continuar'):t('Start using the app','Comenzar a usar la aplicación')}</button></div></div>}

function PageHeading({title,subtitle}:{title:string;subtitle:string}){return <div className="page-heading"><h1>{title}</h1><p>{subtitle}</p></div>}
function EmptyState({icon,title,body}:{icon:ReactNode;title:string;body:string}){return <div className="empty-state"><div className="icon-wrap">{icon}</div><b>{title}</b><span>{body}</span></div>}
function TabButton({label,active,onClick,icon}:{label:string;active:boolean;onClick:()=>void;icon:ReactNode}){return <button className={`tab ${active?'active':''}`} onClick={onClick}>{icon}<span>{label}</span></button>}
function MoreLink({icon,title,body,onClick}:{icon:ReactNode;title:string;body:string;onClick:()=>void}){return <button className="settings-row button-row" onClick={onClick}><span className="settings-icon">{icon}</span><span><b>{title}</b><small>{body}</small></span><ChevronRight/></button>}
function SettingToggle({title,body,value,onChange}:{title:string;body:string;value:boolean;onChange:(v:boolean)=>void}){return <div className="setting-row"><div><b>{title}</b><small>{body}</small></div><button className={`switch ${value?'on':''}`} role="switch" aria-checked={value} onClick={()=>onChange(!value)}><span/></button></div>}
function Metric({label,value}:{label:string;value:number}){return <div className="metric"><strong>{value}</strong><span>{label}</span></div>}
function FullLoader(){const {t}=useRootT();return <div className="full-loader"><Loader2 className="spin"/><span>{t('Opening El Molino Ops…','Abriendo El Molino Ops…')}</span></div>}
function formatDue(v:string|null,locale:'en'|'es'){if(!v)return locale==='es'?'Sin fecha de vencimiento':'No due date';const d=new Date(v);const now=new Date();const same=d.toDateString()===now.toDateString();const code=locale==='es'?'es-US':'en-US';return same?`${locale==='es'?'Hoy':'Today'} ${d.toLocaleTimeString(code,{hour:'numeric',minute:'2-digit'})}`:d.toLocaleString(code,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});}
function timeAgo(v:string,locale:'en'|'es'){const n=Date.now()-new Date(v).getTime();const m=Math.floor(n/60000);if(m<1)return locale==='es'?'ahora mismo':'just now';if(m<60)return locale==='es'?`hace ${m} min`:`${m}m ago`;const h=Math.floor(m/60);if(h<24)return locale==='es'?`hace ${h} h`:`${h}h ago`;const d=Math.floor(h/24);return locale==='es'?`hace ${d} d`:`${d}d ago`;}
function formatBytes(v:number|null,locale:'en'|'es'){if(v==null)return locale==='es'?'tamaño desconocido':'size unknown';if(v<1024)return `${v} B`;if(v<1048576)return `${(v/1024).toFixed(1)} KB`;return `${(v/1048576).toFixed(1)} MB`;}
function rootToken(value:string,locale:'en'|'es'){if(locale!=='es')return value.replaceAll('_',' ');return ({admin:'administrador',manager:'gerente',employee:'empleado',member:'miembro',open:'abierta',done:'completada',cancelled:'cancelada',draft:'borrador',approved:'aprobado',active:'activo',inactive:'inactivo',low:'baja',normal:'normal',high:'alta',urgent:'urgente',internal:'interno',photo:'foto',video:'video',audio:'audio',spreadsheet:'hoja de cálculo',document:'documento',file:'archivo',system:'sistema'} as Record<string,string>)[value]||value.replaceAll('_',' ');}
